SELECT "line_id", "request_number", "item", "quantity", "unit_price", "line_value", "reason", "requested_resolution", "requested_variant", "customer", "order_number", "requested_date", "delivered_date", "in_window", "item_on_order", "share", "item_on_hand", "variant_on_hand", "request_value", "route", 'request above the care threshold' AS "verdict_reason"
FROM (SELECT "t31"."line_id", "t31"."request_number", "t31"."item", "t31"."quantity", "t31"."unit_price", "t31"."line_value", "t31"."reason", "t31"."requested_resolution", "t31"."requested_variant", "t31"."customer", "t31"."order_number", "t31"."requested_date", "t31"."delivered_date", "t31"."in_window", "t31"."item_on_order", "t31"."share", "t31"."item_on_hand", "t31"."variant_on_hand", "t34"."request_value", CASE WHEN "t31"."delivered_date" IS NULL OR "t31"."item_on_order" = 0 THEN 'reject_not_ours' WHEN "t31"."in_window" = 0 THEN 'reject_late' WHEN "t31"."share" > :abuse_share THEN 'reject_abuse' WHEN "t34"."request_value" > :care_threshold THEN 'to_customer_care' WHEN "t31"."line_value" < :small_value AND "t31"."reason" IN ('damaged', 'did_not_arrive') THEN 'refund_no_return' WHEN "t31"."reason" IN ('damaged', 'did_not_arrive') AND "t31"."item_on_hand" >= "t31"."quantity" THEN 'replacement_no_return' WHEN "t31"."requested_resolution" = 'exchange' AND "t31"."variant_on_hand" >= "t31"."quantity" THEN 'exchange' ELSE 'refund_after_return' END AS "route"
        FROM (SELECT "t20"."line_id", "t20"."request_number", "t20"."item", "t20"."quantity", "t20"."unit_price", "t20"."line_value", "t20"."reason", "t20"."requested_resolution", "t20"."requested_variant", "t20"."customer", "t20"."order_number", "t20"."requested_date", "t20"."delivered_date", "t20"."in_window", "t20"."item_on_order", "t20"."share", "t30"."item_on_hand", "t30"."variant_on_hand"
                FROM (SELECT "t7"."line_id", "t7"."request_number", "t7"."item", "t7"."quantity", "t7"."unit_price", "t7"."line_value", "t7"."reason", "t7"."requested_resolution", "t7"."requested_variant", "t7"."customer", "t7"."order_number", "t7"."requested_date", "t7"."delivered_date", "t7"."in_window", "t7"."item_on_order", "t19"."share"
                        FROM (SELECT "t1"."line_id", "t1"."request_number", "t1"."item", "t1"."quantity", "t1"."unit_price", "t1"."line_value", "t1"."reason", "t1"."requested_resolution", "t1"."requested_variant", "t1"."customer", "t1"."order_number", "t1"."requested_date", "t6"."delivered_date", "t6"."in_window", "t6"."item_on_order"
                                FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "order_number", "requested_date"
                                        FROM (SELECT "return_request_line"."line_id", "return_request_line"."request_number", "return_request_line"."line_no", "return_request_line"."item", "return_request_line"."quantity", "return_request_line"."unit_price", "return_request_line"."reason", "return_request_line"."requested_resolution", "return_request_line"."requested_variant", "return_request_line"."state", "return_request_line"."way", "return_request_line"."customer", "return_request"."customer" AS "customer0", "return_request"."order_number", "return_request"."channel", "return_request"."requested_date", "return_request"."state" AS "state0"
                                                FROM "return_request_line"
                                                    INNER JOIN "return_request" ON "return_request_line"."request_number" = "return_request"."request_number") AS "t"
                                        WHERE "t"."state" = 'received') AS "t1"
                                    LEFT JOIN (SELECT "t5"."line_id", "t5"."delivered_date", CASE WHEN "t5"."delivered_date" >= :as_of_minus_return_window_days THEN 1 ELSE 0 END AS "in_window", CASE WHEN "t5"."item" IS NULL THEN 0 ELSE 1 END AS "item_on_order"
                                        FROM (SELECT "t4"."line_id", "t4"."request_number", "t4"."item", "t4"."quantity", "t4"."unit_price", "t4"."line_value", "t4"."reason", "t4"."requested_resolution", "t4"."requested_variant", "t4"."customer", "t4"."order_number", "t4"."requested_date", "order"."channel", "order"."placed_date", "order"."delivered_date", "order"."fulfilling_warehouse", "order"."value", "order"."state", "order"."held_for", "order"."placed_by"
                                                FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "order_number", "requested_date"
                                                        FROM (SELECT "return_request_line0"."line_id", "return_request_line0"."request_number", "return_request_line0"."line_no", "return_request_line0"."item", "return_request_line0"."quantity", "return_request_line0"."unit_price", "return_request_line0"."reason", "return_request_line0"."requested_resolution", "return_request_line0"."requested_variant", "return_request_line0"."state", "return_request_line0"."way", "return_request_line0"."customer", "return_request0"."customer" AS "customer0", "return_request0"."order_number", "return_request0"."channel", "return_request0"."requested_date", "return_request0"."state" AS "state0"
                                                                FROM "return_request_line" AS "return_request_line0"
                                                                    INNER JOIN "return_request" AS "return_request0" ON "return_request_line0"."request_number" = "return_request0"."request_number") AS "t2"
                                                        WHERE "t2"."state" = 'received') AS "t4"
                                                    LEFT JOIN "order" ON "t4"."order_number" = "order"."order_number" AND "t4"."customer" = "order"."customer") AS "t5"
                                            LEFT JOIN "sales_line" ON "t5"."order_number" = "sales_line"."order_number" AND "t5"."item" = "sales_line"."item") AS "t6" ON "t1"."line_id" = "t6"."line_id") AS "t7"
                            LEFT JOIN (SELECT "t16"."line_id", COALESCE("t16"."returned_value", 0) / NULLIF("t18"."bought_value", 0) AS "share"
                                FROM (SELECT "t10"."line_id", "t10"."request_number", "t10"."item", "t10"."quantity", "t10"."unit_price", "t10"."line_value", "t10"."reason", "t10"."requested_resolution", "t10"."requested_variant", "t10"."customer", "t10"."order_number", "t10"."requested_date", "t15"."returned_value"
                                        FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "order_number", "requested_date"
                                                FROM (SELECT "return_request_line1"."line_id", "return_request_line1"."request_number", "return_request_line1"."line_no", "return_request_line1"."item", "return_request_line1"."quantity", "return_request_line1"."unit_price", "return_request_line1"."reason", "return_request_line1"."requested_resolution", "return_request_line1"."requested_variant", "return_request_line1"."state", "return_request_line1"."way", "return_request_line1"."customer", "return_request1"."customer" AS "customer0", "return_request1"."order_number", "return_request1"."channel", "return_request1"."requested_date", "return_request1"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line1"
                                                            INNER JOIN "return_request" AS "return_request1" ON "return_request_line1"."request_number" = "return_request1"."request_number") AS "t8"
                                                WHERE "t8"."state" = 'received') AS "t10"
                                            LEFT JOIN (SELECT "customer", SUM("quantity" * "unit_price") AS "returned_value"
                                                FROM (SELECT "return_request_line2"."line_id", "return_request_line2"."request_number", "return_request_line2"."line_no", "return_request_line2"."item", "return_request_line2"."quantity", "return_request_line2"."unit_price", "return_request_line2"."reason", "return_request_line2"."requested_resolution", "return_request_line2"."requested_variant", "return_request_line2"."state", "return_request_line2"."way", "return_request_line2"."customer", "return_request2"."customer" AS "customer0", "return_request2"."order_number", "return_request2"."channel", "return_request2"."requested_date", "return_request2"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line2"
                                                            INNER JOIN "return_request" AS "return_request2" ON "return_request_line2"."request_number" = "return_request2"."request_number") AS "t11"
                                                WHERE "t11"."requested_date" >= :as_of_minus_365_days AND "t11"."state" <> 'rejected'
                                                GROUP BY "customer") AS "t15" ON "t10"."customer" = "t15"."customer") AS "t16"
                                    LEFT JOIN (SELECT "customer", SUM("ext_sales_price") AS "bought_value"
                                        FROM "sales_line"
                                        WHERE "sold_date" >= :as_of_minus_365_days
                                        GROUP BY "customer") AS "t18" ON "t16"."customer" = "t18"."customer") AS "t19" ON "t7"."line_id" = "t19"."line_id") AS "t20"
                    LEFT JOIN (SELECT "t27"."line_id", "t27"."item_on_hand", COALESCE("t29"."quantity_on_hand", 0) AS "variant_on_hand"
                        FROM (SELECT "t24"."line_id", "t24"."request_number", "t24"."item", "t24"."quantity", "t24"."unit_price", "t24"."line_value", "t24"."reason", "t24"."requested_resolution", "t24"."requested_variant", "t24"."customer", "t24"."order_number", "t24"."requested_date", "t24"."customer_id", "t24"."addr", "t24"."cdemo", "t24"."hdemo", "t24"."birth_year", "t24"."center", "t26"."as_of_date", "t26"."quantity_on_hand", COALESCE("t26"."quantity_on_hand", 0) AS "item_on_hand"
                                FROM (SELECT "t23"."line_id", "t23"."request_number", "t23"."item", "t23"."quantity", "t23"."unit_price", "t23"."line_value", "t23"."reason", "t23"."requested_resolution", "t23"."requested_variant", "t23"."customer", "t23"."order_number", "t23"."requested_date", "customer"."customer_id", "customer"."addr", "customer"."cdemo", "customer"."hdemo", "customer"."birth_year", "customer"."center"
                                        FROM (SELECT "line_id", "request_number", "item", "quantity", "unit_price", "quantity" * "unit_price" AS "line_value", "reason", "requested_resolution", "requested_variant", "customer0" AS "customer", "order_number", "requested_date"
                                                FROM (SELECT "return_request_line3"."line_id", "return_request_line3"."request_number", "return_request_line3"."line_no", "return_request_line3"."item", "return_request_line3"."quantity", "return_request_line3"."unit_price", "return_request_line3"."reason", "return_request_line3"."requested_resolution", "return_request_line3"."requested_variant", "return_request_line3"."state", "return_request_line3"."way", "return_request_line3"."customer", "return_request3"."customer" AS "customer0", "return_request3"."order_number", "return_request3"."channel", "return_request3"."requested_date", "return_request3"."state" AS "state0"
                                                        FROM "return_request_line" AS "return_request_line3"
                                                            INNER JOIN "return_request" AS "return_request3" ON "return_request_line3"."request_number" = "return_request3"."request_number") AS "t21"
                                                WHERE "t21"."state" = 'received') AS "t23"
                                            INNER JOIN "customer" ON "t23"."customer" = "customer"."sk") AS "t24"
                                    LEFT JOIN (SELECT "inventory"."as_of_date", "inventory"."item", "inventory"."warehouse", "inventory"."quantity_on_hand"
                                        FROM "inventory"
                                            INNER JOIN (SELECT "item", "warehouse", MAX("as_of_date") AS "_ttrp_latest_n29"
                                                FROM "inventory"
                                                GROUP BY "item", "warehouse") AS "t25" ON "inventory"."item" = "t25"."item" AND "inventory"."warehouse" = "t25"."warehouse" AND "inventory"."as_of_date" = "t25"."_ttrp_latest_n29") AS "t26" ON "t24"."item" = "t26"."item" AND "t24"."center" = "t26"."warehouse") AS "t27"
                            LEFT JOIN (SELECT "inventory1"."as_of_date", "inventory1"."item", "inventory1"."warehouse", "inventory1"."quantity_on_hand"
                                FROM "inventory" AS "inventory1"
                                    INNER JOIN (SELECT "item", "warehouse", MAX("as_of_date") AS "_ttrp_latest_n29"
                                        FROM "inventory"
                                        GROUP BY "item", "warehouse") AS "t28" ON "inventory1"."item" = "t28"."item" AND "inventory1"."warehouse" = "t28"."warehouse" AND "inventory1"."as_of_date" = "t28"."_ttrp_latest_n29") AS "t29" ON "t27"."requested_variant" = "t29"."item" AND "t27"."center" = "t29"."warehouse") AS "t30" ON "t20"."line_id" = "t30"."line_id") AS "t31"
            LEFT JOIN (SELECT "request_number", SUM("quantity" * "unit_price") AS "request_value"
                FROM "return_request_line"
                GROUP BY "request_number") AS "t34" ON "t31"."request_number" = "t34"."request_number") AS "t35"
WHERE "t35"."route" = 'to_customer_care'
